=== src/server/repositories/base-repository.ts
     1	/**
     2	 * Shared query helpers: cursor encoding, `orgId` predicate construction and the archived-row predicate every other repository composes.
     3	 *
     4	 * Must call (do not reimplement): shouldFilterArchived
     5	 */
     6	import { eq, isNull } from "drizzle-orm";
     7	import { shouldFilterArchived } from "@/lib/soft-delete";
     8	import type { ArchiveScope, OrgId } from "@/types/common";
     9	import type { SQL } from "drizzle-orm";
    10	import type { SQLiteColumn } from "drizzle-orm/sqlite-core";
    11	
    12	const CURSOR_SEPARATOR = "|";
    13	
    14	/**
    15	 * Cursors are opaque to callers: base64url of `<sortValue>|<id>`. Encoding the
    16	 * sort value alongside the id is what lets `listX` resume from a stable point
    17	 * even when two rows share a timestamp.
    18	 */
    19	export function encodeCursor(id: string, sortValue: string): string {
    20	  return Buffer.from(`${sortValue}${CURSOR_SEPARATOR}${id}`, "utf8").toString(
    21	    "base64url",
    22	  );
    23	}
    24	
    25	export function decodeCursor(
    26	  cursor: string,
    27	): { id: string; sortValue: string } | null {
    28	  let decoded: string;
    29	  try {
    30	    decoded = Buffer.from(cursor, "base64url").toString("utf8");
    31	  } catch {
    32	    return null;
    33	  }
    34	
    35	  const separatorAt = decoded.lastIndexOf(CURSOR_SEPARATOR);
    36	  if (separatorAt <= 0 || separatorAt === decoded.length - 1) return null;
    37	
    38	  return {
    39	    sortValue: decoded.slice(0, separatorAt),
    40	    id: decoded.slice(separatorAt + 1),
    41	  };
    42	}
    43	
    44	/**
    45	 * The tenant predicate. Every repository read and write composes this — a
    46	 * query that does not mention `org_id` is a cross-tenant leak waiting to
    47	 * happen, so this is the only sanctioned way to express it.
    48	 */
    49	export function orgPredicate(column: SQLiteColumn, orgId: OrgId): SQL {
    50	  return eq(column, orgId);
    51	}
    52	
    53	/**
    54	 * The soft-delete predicate, or `undefined` when the caller explicitly asked
    55	 * for archived rows. The `includeArchived` decision itself lives in
    56	 * `shouldFilterArchived()` so it cannot drift per repository.
    57	 */
    58	export function livePredicate(
    59	  column: SQLiteColumn,
    60	  scope: ArchiveScope,
    61	): SQL | undefined {
    62	  return shouldFilterArchived(scope) ? isNull(column) : undefined;
    63	}
=== src/server/repositories/_paging.ts
     1	/**
     2	 * Private paging helpers shared by the repositories in this directory.
     3	 *
     4	 * Not part of the public data-access surface — repositories re-export nothing
     5	 * from here. Keyset (cursor) pagination is expressed as a row-value comparison
     6	 * so a page boundary is stable even when two rows share a `created_at`.
     7	 */
     8	import { sql } from "drizzle-orm";
     9	import { decodeCursor, encodeCursor } from "./base-repository";
    10	import { makePage } from "@/types/common";
    11	import type { Page } from "@/types/common";
    12	import type { SQL } from "drizzle-orm";
    13	import type { SQLiteColumn } from "drizzle-orm/sqlite-core";
    14	
    15	export interface KeysetSort {
    16	  readonly sortColumn: SQLiteColumn;
    17	  readonly idColumn: SQLiteColumn;
    18	}
    19	
    20	/**
    21	 * Predicate that resumes a descending listing after `cursor`. Returns
    22	 * `undefined` for a first page or an unparseable cursor — a bad cursor
    23	 * degrades to "start from the top", never to an error page.
    24	 */
    25	export function keysetPredicate(
    26	  sort: KeysetSort,
    27	  cursor: string | null | undefined,
    28	): SQL | undefined {
    29	  if (!cursor) return undefined;
    30	  const decoded = decodeCursor(cursor);
    31	  if (!decoded) return undefined;
    32	
    33	  return sql`(${sort.sortColumn}, ${sort.idColumn}) < (${decoded.sortValue}, ${decoded.id})`;
    34	}
    35	
    36	/** SQLite tolerates a `LIMIT` of `n + 1`; that extra row is the has-more probe. */
    37	export function probeLimit(limit: number): number {
    38	  return Math.max(1, Math.min(limit, 100)) + 1;
    39	}
    40	
    41	/**
    42	 * Turns an over-fetched row array into a `Page`, dropping the probe row and
    43	 * deriving the next cursor from the last row that survived.
    44	 */
    45	export function toPage<TRow, TOut>(
    46	  rows: readonly TRow[],
    47	  limit: number,
    48	  total: number,
    49	  map: (row: TRow) => TOut,
    50	  cursorOf: (row: TRow) => { id: string; sortValue: string },
    51	): Page<TOut> {
    52	  const capped = Math.max(1, Math.min(limit, 100));
    53	  const hasMore = rows.length > capped;
    54	  const visible = hasMore ? rows.slice(0, capped) : rows;
    55	  const last = visible.at(-1);
    56	
    57	  const nextCursor =
    58	    hasMore && last
    59	      ? encodeCursor(cursorOf(last).id, cursorOf(last).sortValue)
    60	      : null;
    61	
    62	  return makePage(visible.map(map), nextCursor, total);
    63	}
    64	
    65	/** Drops the `undefined` slots so `and(...)` never sees a hole. */
    66	export function compact(
    67	  ...predicates: readonly (SQL | undefined)[]
    68	): readonly SQL[] {
    69	  return predicates.filter((value): value is SQL => value !== undefined);
    70	}
