     1	/**
     2	 * ULID generation and validation. Every branded id in the app is produced
     3	 * here, so ids sort lexicographically by creation time and the repositories
     4	 * can use them as pagination cursors without a separate sort column.
     5	 */
     6	/** Crockford base32, minus I, L, O and U. */
     7	const ALPHABET = "0123456789ABCDEFGHJKMNPQRSTVWXYZ";
     8	const TIME_LENGTH = 10;
     9	const RANDOM_LENGTH = 16;
    10	
    11	const ULID_PATTERN = /^[0-9A-HJKMNP-TV-Z]{26}$/;
    12	
    13	function encodeTime(time: number): string {
    14	  let remaining = time;
    15	  let out = "";
    16	  for (let i = 0; i < TIME_LENGTH; i += 1) {
    17	    const mod = remaining % 32;
    18	    out = ALPHABET[mod] + out;
    19	    remaining = (remaining - mod) / 32;
    20	  }
    21	  return out;
    22	}
    23	
    24	function encodeRandom(next: () => number): string {
    25	  let out = "";
    26	  for (let i = 0; i < RANDOM_LENGTH; i += 1) {
    27	    out += ALPHABET[next() % 32];
    28	  }
    29	  return out;
    30	}
    31	
    32	/** A fresh, monotonically-sortable ULID. Uses the Web Crypto API so the same
    33	 *  implementation runs on the server, in the browser and on the edge. */
    34	export function newId(): string {
    35	  const bytes = new Uint8Array(RANDOM_LENGTH);
    36	  globalThis.crypto.getRandomValues(bytes);
    37	  let cursor = 0;
    38	  return encodeTime(Date.now()) + encodeRandom(() => bytes[cursor++] ?? 0);
    39	}
    40	
    41	export function isUlid(value: string): boolean {
    42	  return ULID_PATTERN.test(value);
    43	}
    44	
    45	/**
    46	 * A deterministic id generator for tests and the seed script: same seed,
    47	 * same sequence of ids. Uses a small xorshift PRNG and a fixed timestamp so
    48	 * fixtures are byte-stable across runs.
    49	 */
    50	export function idFactory(seed: number): () => string {
    51	  let state = (seed | 0) || 0x2545_f491;
    52	  let counter = 0;
    53	
    54	  const next = (): number => {
    55	    state ^= state << 13;
    56	    state ^= state >>> 17;
    57	    state ^= state << 5;
    58	    return Math.abs(state);
    59	  };
    60	
    61	  return () => {
    62	    counter += 1;
    63	    // A fixed epoch keeps seeded ids stable; the counter keeps them ordered.
    64	    return encodeTime(1_700_000_000_000 + counter) + encodeRandom(next);
    65	  };
    66	}
