/**
 * Columns added after a table first shipped. `CREATE TABLE IF NOT EXISTS` never
 * alters an existing table, so a database created earlier needs them patched in
 * before the statements that index them run. A fresh database already has them
 * from its `CREATE TABLE`, and a table that does not exist yet is skipped.
 */
const ADDED_COLUMNS: readonly {
  readonly table: string;
  readonly column: string;
  readonly definition: string;
}[] = [{ table: "issues", column: "milestone_id", definition: "TEXT" }];

function addMissingColumns(sqlite: Database.Database): void {
  for (const { table, column, definition } of ADDED_COLUMNS) {
    const existing = sqlite.pragma(`table_info(${table})`) as readonly {
      readonly name: string;
    }[];
    if (existing.length === 0 || existing.some((row) => row.name === column)) {
      continue;
    }
    sqlite.exec(`ALTER TABLE ${table} ADD COLUMN ${column} ${definition}`);
  }
}

