/**
 * Milestone lifecycle inside a project: create, rename or retarget, close (moving its open issues on), reopen, and the progress read.
 *
 * Must call (do not reimplement): assertCan, assertOrgScope, emit, assertNotArchived, milestoneNameKey, compareMilestones, isMilestoneOverdue
 */
import { z } from "zod";
import { MAX_OPEN_MILESTONES_PER_PROJECT } from "@/config/constants";
import { emit } from "@/lib/event-bus";
import {
  MilestoneStateError,
  compareMilestones,
  isMilestoneOverdue,
  milestoneNameKey,
} from "@/lib/milestones";
import { assertCan } from "@/lib/permissions";
import { assertNotArchived } from "@/lib/soft-delete";
import { assertOrgScope } from "@/lib/tenant";
import * as milestoneRepo from "@/server/repositories/milestone-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import {
  NotFoundError,
  actorEnvelope,
  projectResource,
  requireFound,
} from "./_support";
import type {
  CloseMilestoneInput,
  CreateMilestoneInput,
  UpdateMilestoneInput,
} from "@/schemas/milestone";
import type {
  IssueId,
  MilestoneId,
  OrgId,
  ProjectId,
} from "@/types/common";
import type { Actor } from "@/types/member";
import type {
  Milestone,
  MilestoneProgress,
  MilestoneWithProgress,
} from "@/types/milestone";
import type { Project } from "@/types/project";

/** Names are trimmed before they are stored or compared; a blank name is refused. */
const milestoneNameSchema = z.string().trim().min(1, "give the milestone a name");

const NO_PROGRESS: MilestoneProgress = { total: 0, open: 0, closed: 0 };

/**
 * Creates an open milestone once the name is free in the project and the
 * project has room for one more open milestone. Gated like every project write.
 */
export async function createMilestone(
  actor: Actor,
  input: CreateMilestoneInput,
): Promise<Milestone> {
  assertOrgScope(actor, input.orgId);

  const project = await loadProject(input.orgId, input.projectId);
  assertCan(actor, "project:update", projectResource(project));
  assertNotArchived("Project", project.id, project);

  const name = milestoneNameSchema.parse(input.name);
  await assertNameAvailable(input.orgId, project.id, name, null);
  await assertOpenCapacity(input.orgId, project.id);

  const milestone = await milestoneRepo.insertMilestone({
    orgId: input.orgId,
    projectId: project.id,
    name,
    targetDate: input.targetDate,
  });

  await emit("milestone.created", {
    ...actorEnvelope(actor),
    milestoneId: milestone.id,
    projectId: milestone.projectId,
  });

  return milestone;
}

/**
 * Renames or retargets a milestone, open or closed. A `null` target date clears
 * the date; an omitted field is left as it was.
 */
export async function updateMilestone(
  actor: Actor,
  input: UpdateMilestoneInput,
): Promise<Milestone> {
  assertOrgScope(actor, input.orgId);

  const milestone = await loadMilestone(input.orgId, input.milestoneId);
  const project = await loadProject(input.orgId, milestone.projectId);
  assertCan(actor, "project:update", projectResource(project));
  assertNotArchived("Project", project.id, project);

  const name =
    input.name === undefined ? undefined : milestoneNameSchema.parse(input.name);
  if (name !== undefined) {
    await assertNameAvailable(input.orgId, project.id, name, milestone.id);
  }

  return milestoneRepo.updateMilestone(input.orgId, milestone.id, {
    name,
    targetDate: input.targetDate,
  });
}

/**
 * Closes an open milestone. Its open live issues move to `moveOpenIssuesTo`,
 * an open milestone of the same project, or out of any milestone when that is
 * null. Closed and archived issues stay put. Each moved issue's assignee is
 * alerted by the notification fan-out on `milestone.closed`.
 */
export async function closeMilestone(
  actor: Actor,
  input: CloseMilestoneInput,
): Promise<{ milestone: Milestone; movedIssueIds: readonly IssueId[] }> {
  assertOrgScope(actor, input.orgId);

  const milestone = await loadMilestone(input.orgId, input.milestoneId);
  const project = await loadProject(input.orgId, milestone.projectId);
  assertCan(actor, "project:update", projectResource(project));
  assertNotArchived("Project", project.id, project);

  if (milestone.closedAt !== null) throw new MilestoneStateError("closed");

  const target =
    input.moveOpenIssuesTo === null
      ? null
      : await loadMoveTarget(input.orgId, milestone, input.moveOpenIssuesTo);

  const closed = await milestoneRepo.closeMilestone({
    orgId: input.orgId,
    milestoneId: milestone.id,
    moveOpenIssuesTo: target?.id ?? null,
  });

  await emit("milestone.closed", {
    ...actorEnvelope(actor),
    milestoneId: closed.milestone.id,
    projectId: closed.milestone.projectId,
    movedToMilestoneId: target?.id ?? null,
    movedIssueIds: closed.movedIssueIds,
  });

  return closed;
}

/** Reopens a closed milestone, provided the project still has room for one more open. */
export async function reopenMilestone(
  actor: Actor,
  orgId: OrgId,
  milestoneId: MilestoneId,
): Promise<Milestone> {
  assertOrgScope(actor, orgId);

  const milestone = await loadMilestone(orgId, milestoneId);
  const project = await loadProject(orgId, milestone.projectId);
  assertCan(actor, "project:update", projectResource(project));
  assertNotArchived("Project", project.id, project);

  if (milestone.closedAt === null) throw new MilestoneStateError("already_open");
  await assertOpenCapacity(orgId, project.id);

  const reopened = await milestoneRepo.reopenMilestone(orgId, milestone.id);

  await emit("milestone.reopened", {
    ...actorEnvelope(actor),
    milestoneId: reopened.id,
    projectId: reopened.projectId,
  });

  return reopened;
}

/**
 * Every milestone of the project, open ones first, each group ordered by target
 * date. Readable by anyone who may read the project; archived projects still list.
 */
export async function listMilestones(
  actor: Actor,
  orgId: OrgId,
  projectId: ProjectId,
): Promise<readonly MilestoneWithProgress[]> {
  assertOrgScope(actor, orgId);

  const project = await loadProject(orgId, projectId);
  assertCan(actor, "project:read", projectResource(project));

  const milestones = [
    ...(await milestoneRepo.listMilestonesForProject(orgId, project.id)),
  ].sort(compareMilestones);

  const progress = await milestoneRepo.progressByMilestone(
    orgId,
    milestones.map((milestone) => milestone.id),
  );

  const now = new Date();
  return milestones.map((milestone) =>
    withProgress(milestone, progress.get(milestone.id) ?? NO_PROGRESS, now),
  );
}

export async function getMilestone(
  actor: Actor,
  orgId: OrgId,
  milestoneId: MilestoneId,
): Promise<MilestoneWithProgress> {
  assertOrgScope(actor, orgId);

  const milestone = await loadMilestone(orgId, milestoneId);
  const project = await loadProject(orgId, milestone.projectId);
  assertCan(actor, "project:read", projectResource(project));

  const progress = await milestoneRepo.progressByMilestone(orgId, [
    milestone.id,
  ]);
  return withProgress(
    milestone,
    progress.get(milestone.id) ?? NO_PROGRESS,
    new Date(),
  );
}

async function loadMilestone(
  orgId: OrgId,
  milestoneId: MilestoneId,
): Promise<Milestone> {
  return requireFound(
    await milestoneRepo.findMilestoneById(orgId, milestoneId),
    "Milestone",
    milestoneId,
  );
}

async function loadProject(orgId: OrgId, projectId: ProjectId): Promise<Project> {
  return requireFound(
    await projectRepo.findProjectById(orgId, projectId),
    "Project",
    projectId,
  );
}

/**
 * The target of a close must be another open milestone of the same project.
 * The milestone itself, another project's milestone and an unknown id all look
 * the same from outside, so they share one `NotFoundError`.
 */
async function loadMoveTarget(
  orgId: OrgId,
  milestone: Milestone,
  targetId: MilestoneId,
): Promise<Milestone> {
  const target = await milestoneRepo.findMilestoneById(orgId, targetId);
  if (
    target === null ||
    target.id === milestone.id ||
    target.projectId !== milestone.projectId
  ) {
    throw new NotFoundError("Milestone", targetId);
  }
  if (target.closedAt !== null) throw new MilestoneStateError("closed");
  return target;
}

async function assertNameAvailable(
  orgId: OrgId,
  projectId: ProjectId,
  name: string,
  exceptId: MilestoneId | null,
): Promise<void> {
  const key = milestoneNameKey(name);
  const siblings = await milestoneRepo.listMilestonesForProject(orgId, projectId);
  const taken = siblings.some(
    (sibling) =>
      sibling.id !== exceptId && milestoneNameKey(sibling.name) === key,
  );
  if (taken) throw new MilestoneStateError("name_taken");
}

async function assertOpenCapacity(orgId: OrgId, projectId: ProjectId): Promise<void> {
  const open = await milestoneRepo.countOpenMilestones(orgId, projectId);
  if (open >= MAX_OPEN_MILESTONES_PER_PROJECT) {
    throw new MilestoneStateError("too_many_open");
  }
}

function withProgress(
  milestone: Milestone,
  progress: MilestoneProgress,
  now: Date,
): MilestoneWithProgress {
  return {
    milestone,
    progress,
    overdue: isMilestoneOverdue(milestone, progress.open, now),
  };
}

