import type { Project } from "@/types/project";

/** Names are trimmed before they are stored or compared; a blank name is refused. */
const milestoneNameSchema = z.string().trim().min(1, "give the milestone a name");

const NO_PROGRESS: MilestoneProgress = { total: 0, open: 0, closed: 0 };

/**
 * Creates an open milestone once the name is free in the project and the
 * project has room for one more open milestone. Gated like every project write.
 */
export async function createMilestone(
  actor: Actor,
  input: CreateMilestoneInput,
): Promise<Milestone> {
  assertOrgScope(actor, input.orgId);

  const project = await loadProject(input.orgId, input.projectId);
  assertCan(actor, "project:update", projectResource(project));
  assertNotArchived("Project", project.id, project);

  const name = milestoneNameSchema.parse(input.name);
  await assertNameAvailable(input.orgId, project.id, name, null);
  await assertOpenCapacity(input.orgId, project.id);

  const milestone = await milestoneRepo.insertMilestone({
    orgId: input.orgId,
    projectId: project.id,
    name,
    targetDate: input.targetDate,
  });

  await emit("milestone.created", {
    ...actorEnvelope(actor),
    milestoneId: milestone.id,
    projectId: milestone.projectId,
  });

  return milestone;
}

/**
 * Renames or retargets a milestone, open or closed. A `null` target date clears
 * the date; an omitted field is left as it was.
 */
export async function updateMilestone(
  actor: Actor,
  input: UpdateMilestoneInput,
): Promise<Milestone> {
  assertOrgScope(actor, input.orgId);

  const milestone = await loadMilestone(input.orgId, input.milestoneId);
  const project = await loadProject(input.orgId, milestone.projectId);
  assertCan(actor, "project:update", projectResource(project));
  assertNotArchived("Project", project.id, project);

  const name =
    input.name === undefined ? undefined : milestoneNameSchema.parse(input.name);
  if (name !== undefined) {
    await assertNameAvailable(input.orgId, project.id, name, milestone.id);
  }

  return milestoneRepo.updateMilestone(input.orgId, milestone.id, {
    name,
    targetDate: input.targetDate,
  });
}

/**
 * Closes an open milestone. Its open live issues move to `moveOpenIssuesTo`,
 * an open milestone of the same project, or out of any milestone when that is
 * null. Closed and archived issues stay put. Each moved issue's assignee is
 * alerted by the notification fan-out on `milestone.closed`.
 */
export async function closeMilestone(
  actor: Actor,
  input: CloseMilestoneInput,
): Promise<{ milestone: Milestone; movedIssueIds: readonly IssueId[] }> {
  assertOrgScope(actor, input.orgId);

  const milestone = await loadMilestone(input.orgId, input.milestoneId);
  const project = await loadProject(input.orgId, milestone.projectId);
  assertCan(actor, "project:update", projectResource(project));
  assertNotArchived("Project", project.id, project);

