    ...actorEnvelope(actor),
    milestoneId: closed.milestone.id,
    projectId: closed.milestone.projectId,
    movedToMilestoneId: target?.id ?? null,
    movedIssueIds: closed.movedIssueIds,
  });

  return closed;
}

/** Reopens a closed milestone, provided the project still has room for one more open. */
export async function reopenMilestone(
  actor: Actor,
  orgId: OrgId,
  milestoneId: MilestoneId,
): Promise<Milestone> {
  assertOrgScope(actor, orgId);

  const milestone = await loadMilestone(orgId, milestoneId);
  const project = await loadProject(orgId, milestone.projectId);
  assertCan(actor, "project:update", projectResource(project));
  assertNotArchived("Project", project.id, project);

  if (milestone.closedAt === null) throw new MilestoneStateError("already_open");
  await assertOpenCapacity(orgId, project.id);

  const reopened = await milestoneRepo.reopenMilestone(orgId, milestone.id);

  await emit("milestone.reopened", {
    ...actorEnvelope(actor),
    milestoneId: reopened.id,
    projectId: reopened.projectId,
  });

  return reopened;
}

/**
 * Every milestone of the project, open ones first, each group ordered by target
 * date. Readable by anyone who may read the project; archived projects still list.
 */
export async function listMilestones(
  actor: Actor,
  orgId: OrgId,
  projectId: ProjectId,
): Promise<readonly MilestoneWithProgress[]> {
  assertOrgScope(actor, orgId);

  const project = await loadProject(orgId, projectId);
  assertCan(actor, "project:read", projectResource(project));

  const milestones = [
    ...(await milestoneRepo.listMilestonesForProject(orgId, project.id)),
  ].sort(compareMilestones);

  const progress = await milestoneRepo.progressByMilestone(
    orgId,
    milestones.map((milestone) => milestone.id),
  );

  const now = new Date();
  return milestones.map((milestone) =>
    withProgress(milestone, progress.get(milestone.id) ?? NO_PROGRESS, now),
  );
}

export async function getMilestone(
  actor: Actor,
  orgId: OrgId,
  milestoneId: MilestoneId,
): Promise<MilestoneWithProgress> {
  assertOrgScope(actor, orgId);

  const milestone = await loadMilestone(orgId, milestoneId);
  const project = await loadProject(orgId, milestone.projectId);
  assertCan(actor, "project:read", projectResource(project));

  const progress = await milestoneRepo.progressByMilestone(orgId, [
    milestone.id,
  ]);
  return withProgress(
    milestone,
    progress.get(milestone.id) ?? NO_PROGRESS,
    new Date(),
  );
}

async function loadMilestone(
  orgId: OrgId,
  milestoneId: MilestoneId,
): Promise<Milestone> {
  return requireFound(
    await milestoneRepo.findMilestoneById(orgId, milestoneId),
    "Milestone",
    milestoneId,
  );
}

async function loadProject(orgId: OrgId, projectId: ProjectId): Promise<Project> {
  return requireFound(
    await projectRepo.findProjectById(orgId, projectId),
    "Project",
    projectId,
  );
}

/**
 * The target of a close must be another open milestone of the same project.
 * The milestone itself, another project's milestone and an unknown id all look
 * the same from outside, so they share one `NotFoundError`.
 */
async function loadMoveTarget(
  orgId: OrgId,
  milestone: Milestone,
  targetId: MilestoneId,
): Promise<Milestone> {
  const target = await milestoneRepo.findMilestoneById(orgId, targetId);
  if (
    target === null ||
    target.id === milestone.id ||
    target.projectId !== milestone.projectId
  ) {
    throw new NotFoundError("Milestone", targetId);
  }
  if (target.closedAt !== null) throw new MilestoneStateError("closed");
  return target;
}

async function assertNameAvailable(
  orgId: OrgId,
  projectId: ProjectId,
  name: string,
  exceptId: MilestoneId | null,
): Promise<void> {
  const key = milestoneNameKey(name);
  const siblings = await milestoneRepo.listMilestonesForProject(orgId, projectId);
  const taken = siblings.some(
    (sibling) =>
      sibling.id !== exceptId && milestoneNameKey(sibling.name) === key,
  );
  if (taken) throw new MilestoneStateError("name_taken");
}

async function assertOpenCapacity(orgId: OrgId, projectId: ProjectId): Promise<void> {
  const open = await milestoneRepo.countOpenMilestones(orgId, projectId);
  if (open >= MAX_OPEN_MILESTONES_PER_PROJECT) {
    throw new MilestoneStateError("too_many_open");
  }
}

function withProgress(
  milestone: Milestone,
  progress: MilestoneProgress,
  now: Date,
): MilestoneWithProgress {
  return {
    milestone,
    progress,
    overdue: isMilestoneOverdue(milestone, progress.open, now),
  };
}

