/**
 * Milestones: names, the open-milestone cap, closing and its issue moves, reopening,
 * progress and overdue, moving issues, tenancy, and the alerts and audit rows.
 */
import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { MAX_OPEN_MILESTONES_PER_PROJECT } from "@/config/constants";
import { MilestoneStateError } from "@/lib/milestones";
import { PermissionDeniedError } from "@/lib/permissions";
import { AlreadyArchivedError } from "@/lib/soft-delete";
import { TenantScopeError } from "@/lib/tenant";
import * as issueRepo from "@/server/repositories/issue-repository";
import { NotFoundError } from "@/server/services/_support";
import {
  listActivity,
  registerActivityListeners,
} from "@/server/services/activity-service";
import * as issueService from "@/server/services/issue-service";
import * as milestoneService from "@/server/services/milestone-service";
import * as notificationService from "@/server/services/notification-service";
import * as projectService from "@/server/services/project-service";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import { toIsoTimestamp } from "@/types/common";
import type {
  IsoTimestamp,
  IssueId,
  MilestoneId,
  ProjectId,
  UserId,
} from "@/types/common";
import type { Actor } from "@/types/member";
import type { Issue } from "@/types/issue";
import type { Milestone } from "@/types/milestone";

let cleanup: () => void;
let tenant: Tenant;
let detachAudit: () => void;
let projectCount = 0;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  tenant = await createTenant("milestones", "growth");
  detachAudit = registerActivityListeners();
});

afterAll(() => {
  detachAudit();
  cleanup();
});

const { admin, member, viewer } = tenant.actors;

/** A project with no milestones or issues, so each case starts from a clean slate. */
async function freshProject(): Promise<ProjectId> {
  projectCount += 1;
  const project = await projectService.createProject(tenant.actors.owner, {
    orgId: tenant.org.id,
    name: `Milestone project ${projectCount}`,
    slug: `milestone-project-${projectCount}`,
    key: `MP${projectCount}`,
    description: null,
    visibility: "org",
    leadId: null,
    color: "#6366f1",
    targetDate: null,
  });
  return project.id;
}

function create(
  projectId: ProjectId,
  name: string,
  targetDate: IsoTimestamp | null = null,
  actor: Actor = member,
): Promise<Milestone> {
  return milestoneService.createMilestone(actor, {
    orgId: tenant.org.id,
    projectId,
    name,
    targetDate,
  });
}

function close(milestoneId: MilestoneId, moveOpenIssuesTo: MilestoneId | null = null) {
  return milestoneService.closeMilestone(member, {
    orgId: tenant.org.id,
    milestoneId,
    moveOpenIssuesTo,
  });
}

function createIssue(
  projectId: ProjectId,
  title: string,
  milestoneId: MilestoneId | null,
  assigneeId: UserId | null = null,
): Promise<Issue> {
  return issueService.createIssue(member, {
    ...issueInput(tenant.org.id, projectId, { title, assigneeId }),
    milestoneId,
  });
}

async function issueMilestone(issueId: IssueId): Promise<MilestoneId | null> {
  const issue = await issueRepo.findIssueById(tenant.org.id, issueId);
  return issue?.milestoneId ?? null;
}

describe("names", () => {
  it("refuses a name held by a closed milestone, ignoring case and surrounding spaces", async () => {
    const projectId = await freshProject();
    const beta = await create(projectId, "Beta");
    await close(beta.id);

    await expect(create(projectId, "  beta ")).rejects.toMatchObject({
      code: "conflict",
      reason: "name_taken",
    });
  });

  it("allows the same name in another project", async () => {
    const projectId = await freshProject();
    const otherProjectId = await freshProject();
    await create(projectId, "Launch");

    await expect(create(otherProjectId, "Launch")).resolves.toMatchObject({
      name: "Launch",
    });
  });

  it("refuses a rename onto another milestone's name, but lets a milestone change its own case", async () => {
    const projectId = await freshProject();
    const alpha = await create(projectId, "Alpha");
    const beta = await create(projectId, "Beta");

    await expect(
      milestoneService.updateMilestone(member, {
        orgId: tenant.org.id,
        milestoneId: beta.id,
        name: "ALPHA",
      }),
    ).rejects.toMatchObject({ reason: "name_taken" });

    await expect(
      milestoneService.updateMilestone(member, {
        orgId: tenant.org.id,
        milestoneId: alpha.id,
        name: "ALPHA",
      }),
    ).resolves.toMatchObject({ name: "ALPHA" });
  });

  it("refuses a blank name", async () => {
    const projectId = await freshProject();
    await expect(create(projectId, "   ")).rejects.toThrow();
  });
});

describe("open-milestone cap", () => {
  it("refuses creation and reopening at the cap, and counts only open milestones", async () => {
    const projectId = await freshProject();
    const milestones: Milestone[] = [];
    for (let index = 0; index < MAX_OPEN_MILESTONES_PER_PROJECT; index += 1) {
      milestones.push(await create(projectId, `Open ${index}`));
    }

    await expect(create(projectId, "One too many")).rejects.toMatchObject({
      reason: "too_many_open",
    });

    await close(milestones[0]!.id);
    await expect(create(projectId, "Fits after a close")).resolves.toMatchObject({
      closedAt: null,
    });

    await expect(
      milestoneService.reopenMilestone(member, tenant.org.id, milestones[0]!.id),
    ).rejects.toMatchObject({ reason: "too_many_open" });
  });
});

describe("closing", () => {
  it("moves open live issues to the target and leaves closed and archived ones where they are", async () => {
    const projectId = await freshProject();
    const from = await create(projectId, "From");
    const to = await create(projectId, "To");

    const open = await createIssue(projectId, "Still open", from.id);
    const done = await createIssue(projectId, "Already done", from.id);
    await issueService.changeIssueStatus(member, {
      orgId: tenant.org.id,
      issueId: done.id,
      status: "done",
    });
    const archived = await createIssue(projectId, "Archived", from.id);
    await issueService.archiveIssue(member, tenant.org.id, archived.id);
    const outside = await createIssue(projectId, "Never in it", null);

    const result = await close(from.id, to.id);

    expect(result.milestone.closedAt).not.toBeNull();
    expect(result.movedIssueIds).toEqual([open.id]);
    expect(await issueMilestone(open.id)).toBe(to.id);
    expect(await issueMilestone(done.id)).toBe(from.id);
    expect(await issueMilestone(archived.id)).toBe(from.id);
    expect(await issueMilestone(outside.id)).toBeNull();
  });

  it("takes open issues out of any milestone when no target is named", async () => {
    const projectId = await freshProject();
    const from = await create(projectId, "Dropped");
    const open = await createIssue(projectId, "Loose", from.id);

    const result = await close(from.id);

    expect(result.movedIssueIds).toEqual([open.id]);
    expect(await issueMilestone(open.id)).toBeNull();
  });

  it("refuses a closed target, the milestone itself, another project's milestone and an unknown id, changing nothing", async () => {
    const projectId = await freshProject();
    const otherProjectId = await freshProject();
    const from = await create(projectId, "Source");
    const closedTarget = await create(projectId, "Shut");
    await close(closedTarget.id);
    const foreign = await create(otherProjectId, "Foreign");
    const open = await createIssue(projectId, "Stays put", from.id);

    await expect(close(from.id, closedTarget.id)).rejects.toMatchObject({
      reason: "closed",
    });
    await expect(close(from.id, from.id)).rejects.toBeInstanceOf(NotFoundError);
    await expect(close(from.id, foreign.id)).rejects.toBeInstanceOf(NotFoundError);
    await expect(
      close(from.id, "01HZZZZZZZZZZZZZZZZZZZZZZZ" as MilestoneId),
    ).rejects.toBeInstanceOf(NotFoundError);

    expect(await issueMilestone(open.id)).toBe(from.id);
    const listed = await milestoneService.listMilestones(member, tenant.org.id, projectId);
    expect(listed.find((item) => item.milestone.id === from.id)?.milestone.closedAt).toBeNull();
  });

  it("refuses to close a milestone that is already closed", async () => {
    const projectId = await freshProject();
    const done = await create(projectId, "Once");
    await close(done.id);

    await expect(close(done.id)).rejects.toMatchObject({ reason: "closed" });
  });
});

describe("reopening", () => {
  it("refuses to reopen an open milestone and reopens a closed one", async () => {
    const projectId = await freshProject();
    const milestone = await create(projectId, "Round trip");

    await expect(
      milestoneService.reopenMilestone(member, tenant.org.id, milestone.id),
    ).rejects.toMatchObject({ reason: "already_open" });

    await close(milestone.id);
    const reopened = await milestoneService.reopenMilestone(
      member,
      tenant.org.id,
      milestone.id,
    );
    expect(reopened.closedAt).toBeNull();
  });
});

describe("progress, overdue and listing order", () => {
  it("counts live issues by state and marks overdue only when open, dated in the past and holding open issues", async () => {
    const projectId = await freshProject();
    const past = toIsoTimestamp("2020-01-01T00:00:00.000Z");
    const late = await create(projectId, "Late", past);
    const emptyPast = await create(projectId, "Empty past", past);
    const future = await create(projectId, "Future", toIsoTimestamp("2999-01-01T00:00:00.000Z"));
    const undated = await create(projectId, "Undated");

    const lateOpen = await createIssue(projectId, "Late open", late.id);
    const lateDone = await createIssue(projectId, "Late done", late.id);
    await issueService.changeIssueStatus(member, {
      orgId: tenant.org.id,
      issueId: lateDone.id,
      status: "done",
    });
    const lateCanceled = await createIssue(projectId, "Late canceled", late.id);
    await issueService.changeIssueStatus(member, {
      orgId: tenant.org.id,
      issueId: lateCanceled.id,
      status: "canceled",
    });
    await createIssue(projectId, "Future open", future.id);
    await createIssue(projectId, "Undated open", undated.id);

    expect(lateOpen.milestoneId).toBe(late.id);

    const listed = await milestoneService.listMilestones(member, tenant.org.id, projectId);
    const byName = new Map(listed.map((item) => [item.milestone.name, item]));

    expect(byName.get("Late")?.progress).toEqual({ total: 3, open: 1, closed: 2 });
    expect(byName.get("Late")?.overdue).toBe(true);
    expect(byName.get("Empty past")?.progress).toEqual({ total: 0, open: 0, closed: 0 });
    expect(byName.get("Empty past")?.overdue).toBe(false);
    expect(byName.get("Future")?.overdue).toBe(false);
    expect(byName.get("Undated")?.overdue).toBe(false);
  });

  it("counts every live issue, not just the first page", async () => {
    const projectId = await freshProject();
    const big = await create(projectId, "Big");
    for (let index = 0; index < 101; index += 1) {
      await createIssue(projectId, `Bulk ${index}`, big.id);
    }

    const { progress } = await milestoneService.getMilestone(member, tenant.org.id, big.id);
    expect(progress).toEqual({ total: 101, open: 101, closed: 0 });
  });

  it("lists open milestones first, by target date with undated last, then closed ones", async () => {
    const projectId = await freshProject();
    const later = await create(projectId, "Later", toIsoTimestamp("2030-06-01T00:00:00.000Z"));
    const sooner = await create(projectId, "Sooner", toIsoTimestamp("2030-01-01T00:00:00.000Z"));
    const soonerTwin = await create(projectId, "Sooner twin", toIsoTimestamp("2030-01-01T00:00:00.000Z"));
    const undated = await create(projectId, "Undated");
    const shut = await create(projectId, "Shut", toIsoTimestamp("2025-01-01T00:00:00.000Z"));
    await close(shut.id);

    const listed = await milestoneService.listMilestones(member, tenant.org.id, projectId);

    expect(listed.map((item) => item.milestone.id)).toEqual([
      sooner.id,
      soonerTwin.id,
      later.id,
      undated.id,
      shut.id,
    ]);
  });
});

describe("moving issues", () => {
  it("puts an issue into an open milestone of its project and takes it back out", async () => {
    const projectId = await freshProject();
    const target = await create(projectId, "Target");
    const issue = await createIssue(projectId, "Movable", null);

    const moved = await issueService.setIssueMilestone(member, {
      orgId: tenant.org.id,
      issueId: issue.id,
      milestoneId: target.id,
    });
    expect(moved.milestoneId).toBe(target.id);

    const taken = await issueService.setIssueMilestone(member, {
      orgId: tenant.org.id,
      issueId: issue.id,
      milestoneId: null,
    });
    expect(taken.milestoneId).toBeNull();
  });

  it("refuses a closed milestone, another project's, another workspace's and an unknown one", async () => {
    const projectId = await freshProject();
    const otherProjectId = await freshProject();
    const shut = await create(projectId, "Shut for moves");
    await close(shut.id);
    const foreign = await create(otherProjectId, "Elsewhere");
    const other = await createTenant("milestoneforeign", "growth");
    const abroad = await milestoneService.createMilestone(other.actors.member, {
      orgId: other.org.id,
      projectId: other.project.id,
      name: "Abroad",
      targetDate: null,
    });
    const issue = await createIssue(projectId, "Refused move", null);

    const attempt = (milestoneId: MilestoneId) =>
      issueService.setIssueMilestone(member, {
        orgId: tenant.org.id,
        issueId: issue.id,
        milestoneId,
      });

    await expect(attempt(shut.id)).rejects.toMatchObject({ reason: "closed" });
    await expect(attempt(foreign.id)).rejects.toBeInstanceOf(NotFoundError);
    await expect(attempt(abroad.id)).rejects.toBeInstanceOf(NotFoundError);
    await expect(
      attempt("01HZZZZZZZZZZZZZZZZZZZZZZZ" as MilestoneId),
    ).rejects.toBeInstanceOf(NotFoundError);
    expect(await issueMilestone(issue.id)).toBeNull();
  });

  it("refuses an archived issue and everything in an archived project", async () => {
    const projectId = await freshProject();
    const target = await create(projectId, "Locked");
    const archivedIssue = await createIssue(projectId, "Archived issue", null);
    await issueService.archiveIssue(member, tenant.org.id, archivedIssue.id);

    await expect(
      issueService.setIssueMilestone(member, {
        orgId: tenant.org.id,
        issueId: archivedIssue.id,
        milestoneId: target.id,
      }),
    ).rejects.toBeInstanceOf(AlreadyArchivedError);

    const liveIssue = await createIssue(projectId, "Live issue", null);
    await projectService.archiveProject(admin, {
      orgId: tenant.org.id,
      projectId,
      archiveIssues: false,
    });

    await expect(
      issueService.setIssueMilestone(member, {
        orgId: tenant.org.id,
        issueId: liveIssue.id,
        milestoneId: target.id,
      }),
    ).rejects.toBeInstanceOf(AlreadyArchivedError);
  });

  it("creates nothing when an issue is created into a closed milestone", async () => {
    const projectId = await freshProject();
    const shut = await create(projectId, "Shut at birth");
    await close(shut.id);
    const before = await issueRepo.countIssues(tenant.org.id, projectId);

    await expect(createIssue(projectId, "Refused", shut.id)).rejects.toMatchObject({
      reason: "closed",
    });
    expect(await issueRepo.countIssues(tenant.org.id, projectId)).toBe(before);
  });

  it("stores the milestone when an issue is created into an open one", async () => {
    const projectId = await freshProject();
    const open = await create(projectId, "Open at birth");

    const issue = await createIssue(projectId, "Born in a milestone", open.id);
    expect(issue.milestoneId).toBe(open.id);
    expect(await issueMilestone(issue.id)).toBe(open.id);
  });
});

describe("tenancy and permissions", () => {
  it("refuses another workspace's orgId on every operation with TenantScopeError", async () => {
    const projectId = await freshProject();
    const milestone = await create(projectId, "Scoped");
    const issue = await createIssue(projectId, "Scoped issue", null);
    const foreignOrgId = createTenant.name ? tenant.org.id : tenant.org.id;
    const other = await createTenant("milestonescope", "growth");
    void foreignOrgId;

    const attempts = [
      milestoneService.createMilestone(member, {
        orgId: other.org.id,
        projectId,
        name: "Wrong org",
        targetDate: null,
      }),
      milestoneService.updateMilestone(member, {
        orgId: other.org.id,
        milestoneId: milestone.id,
        name: "Renamed",
      }),
      milestoneService.closeMilestone(member, {
        orgId: other.org.id,
        milestoneId: milestone.id,
        moveOpenIssuesTo: null,
      }),
      milestoneService.reopenMilestone(member, other.org.id, milestone.id),
      milestoneService.listMilestones(member, other.org.id, projectId),
      milestoneService.getMilestone(member, other.org.id, milestone.id),
      issueService.setIssueMilestone(member, {
        orgId: other.org.id,
        issueId: issue.id,
        milestoneId: milestone.id,
      }),
    ];

    for (const attempt of attempts) {
      await expect(attempt).rejects.toBeInstanceOf(TenantScopeError);
    }
  });

  it("does not reveal another workspace's milestones as anything but missing", async () => {
    const projectId = await freshProject();
    const milestone = await create(projectId, "Private");
    const other = await createTenant("milestoneprivate", "growth");

    await expect(
      milestoneService.getMilestone(other.actors.owner, other.org.id, milestone.id),
    ).rejects.toBeInstanceOf(NotFoundError);
  });

  it("refuses changes from viewers, and lets them list", async () => {
    const projectId = await freshProject();
    await expect(create(projectId, "Viewer's", null, viewer)).rejects.toBeInstanceOf(
      PermissionDeniedError,
    );
    await expect(
      milestoneService.listMilestones(viewer, tenant.org.id, projectId),
    ).resolves.toEqual([]);
  });

  it("refuses every change to an archived project but still lists its milestones", async () => {
    const projectId = await freshProject();
    const milestone = await create(projectId, "Frozen");
    await projectService.archiveProject(admin, {
      orgId: tenant.org.id,
      projectId,
      archiveIssues: false,
    });

    await expect(create(projectId, "Too late")).rejects.toBeInstanceOf(AlreadyArchivedError);
    await expect(
      milestoneService.updateMilestone(member, {
        orgId: tenant.org.id,
        milestoneId: milestone.id,
        name: "Thawed",
      }),
    ).rejects.toBeInstanceOf(AlreadyArchivedError);
    await expect(close(milestone.id)).rejects.toBeInstanceOf(AlreadyArchivedError);

    const listed = await milestoneService.listMilestones(member, tenant.org.id, projectId);
    expect(listed.map((item) => item.milestone.id)).toEqual([milestone.id]);
  });
});

describe("alerts and audit", () => {
  it("alerts each moved issue's assignee once, and never the person who closed the milestone", async () => {
    const projectId = await freshProject();
    const from = await create(projectId, "Alert source");
    const to = await create(projectId, "Alert target");
    const forViewer = await createIssue(projectId, "Viewer's issue", from.id, viewer.userId);
    await createIssue(projectId, "Closer's issue", from.id, member.userId);
    await createIssue(projectId, "Nobody's issue", from.id, null);

    await close(from.id, to.id);

    const viewerAlerts = await notificationService.listNotifications(admin, {
      orgId: tenant.org.id,
      recipientId: viewer.userId,
      unreadOnly: false,
      kind: ["issue_milestone_changed"],
      limit: 25,
    });
    expect(viewerAlerts.items).toHaveLength(1);
    expect(viewerAlerts.items[0]?.href).toBe(`/issues/${forViewer.id}`);

    const closerAlerts = await notificationService.listNotifications(admin, {
      orgId: tenant.org.id,
      recipientId: member.userId,
      unreadOnly: false,
      kind: ["issue_milestone_changed"],
      limit: 25,
    });
    expect(closerAlerts.items).toHaveLength(0);
  });

  it("records create, close and reopen in the audit log against the milestone", async () => {
    const projectId = await freshProject();
    const milestone = await create(projectId, "Audited");
    await close(milestone.id);
    await milestoneService.reopenMilestone(member, tenant.org.id, milestone.id);

    const page = await listActivity(admin, {
      orgId: tenant.org.id,
      subjectKind: "milestone",
      limit: 100,
    });
    const ours = page.items.filter((event) => event.subjectId === milestone.id);

    expect(ours.map((event) => event.action).sort()).toEqual([
      "milestone.closed",
      "milestone.created",
      "milestone.reopened",
    ]);
    for (const event of ours) {
      expect(event.projectId).toBe(projectId);
      expect(event.actorId).toBe(member.userId);
    }
  });
});

