/**
 * Milestone rules that need no database: the state error the service layer
 * throws, the name comparison, the list order and the overdue predicate.
 *
 * Must call (do not reimplement): milestoneNameKey, compareMilestones, isMilestoneOverdue
 */
import { MAX_OPEN_MILESTONES_PER_PROJECT } from "@/config/constants";
import type { Milestone } from "@/types/milestone";

export type MilestoneStateReason =
  | "closed"
  | "already_open"
  | "too_many_open"
  | "name_taken";

const REASON_MESSAGES: Readonly<Record<MilestoneStateReason, string>> = {
  closed: "The milestone is closed.",
  already_open: "The milestone is already open.",
  too_many_open: `A project can have at most ${MAX_OPEN_MILESTONES_PER_PROJECT} open milestones.`,
  name_taken: "Another milestone in this project already has that name.",
};

/**
 * A milestone is in the wrong state for the operation: it is closed where an
 * open one is needed, it is open where a closed one is needed, the project is
 * at its open-milestone cap, or the name is taken. Mapped to `conflict`.
 */
export class MilestoneStateError extends Error {
  readonly code = "conflict" as const;

  constructor(readonly reason: MilestoneStateReason) {
    super(REASON_MESSAGES[reason]);
    this.name = "MilestoneStateError";
  }
}

/** Names are unique without regard to letter case or surrounding spaces. */
export function milestoneNameKey(name: string): string {
  return name.trim().toLowerCase();
}

/**
 * Open milestones first, then closed ones. Within each group the earliest
 * target date comes first and milestones without one come last; ties go to the
 * older milestone.
 */
export function compareMilestones(a: Milestone, b: Milestone): number {
  const groupA = a.closedAt === null ? 0 : 1;
  const groupB = b.closedAt === null ? 0 : 1;
  if (groupA !== groupB) return groupA - groupB;

  if (a.targetDate !== b.targetDate) {
    if (a.targetDate === null) return 1;
    if (b.targetDate === null) return -1;
    const byDate = Date.parse(a.targetDate) - Date.parse(b.targetDate);
    if (byDate !== 0) return byDate;
  }

  if (a.createdAt !== b.createdAt) return a.createdAt < b.createdAt ? -1 : 1;
  return a.id < b.id ? -1 : a.id > b.id ? 1 : 0;
}

/**
 * Open, dated strictly in the past, and still holding open issues. A milestone
 * without a target date is never overdue.
 */
export function isMilestoneOverdue(
  milestone: Milestone,
  openIssues: number,
  now: Date,
): boolean {
  if (milestone.closedAt !== null || milestone.targetDate === null) return false;
  if (openIssues === 0) return false;
  return Date.parse(milestone.targetDate) < now.getTime();
}

/**
 * Milestone rows, their progress counters, and the close that moves open issues out of them.
 *
 * Must call (do not reimplement): orgPredicate, livePredicate, milestoneNameKey, toMilestone
 */
import { and, count, eq, inArray, isNull, notInArray } from "drizzle-orm";
import { newId } from "@/lib/id";
import { milestoneNameKey } from "@/lib/milestones";
import { getDb, issues, milestones } from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { CLOSED_ISSUE_STATUSES } from "@/types/issue";
import { livePredicate, orgPredicate } from "./base-repository";
import { compact } from "./_paging";
import { toMilestone } from "./_mappers";
import type {
  IsoTimestamp,
  IssueId,
  MilestoneId,
  OrgId,
  ProjectId,
} from "@/types/common";
import type { Milestone, MilestoneProgress } from "@/types/milestone";

/** Fields a rename or retarget may change; `undefined` leaves a field alone. */
export interface MilestoneChanges {
  readonly name?: string;
  readonly targetDate?: IsoTimestamp | null;
}

export async function findMilestoneById(
  orgId: OrgId,
  milestoneId: MilestoneId,
): Promise<Milestone | null> {
  const row = getDb()
    .select()
    .from(milestones)
    .where(
      and(
        orgPredicate(milestones.orgId, orgId),
        eq(milestones.id, milestoneId),
      ),
    )
    .get();
  return row ? toMilestone(row) : null;
}

/** Every milestone of the project, closed ones included, in no particular order. */
export async function listMilestonesForProject(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<readonly Milestone[]> {
  const rows = getDb()
    .select()
    .from(milestones)
    .where(
      and(
        orgPredicate(milestones.orgId, orgId),
        eq(milestones.projectId, projectId),
      ),
    )
    .all();
  return rows.map(toMilestone);
}

export async function countOpenMilestones(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<number> {
  const row = getDb()
    .select({ value: count() })
    .from(milestones)
    .where(
      and(
        orgPredicate(milestones.orgId, orgId),
        eq(milestones.projectId, projectId),
        isNull(milestones.closedAt),
      ),
    )
    .get();
  return row?.value ?? 0;
}

export async function insertMilestone(input: {
  readonly orgId: OrgId;
  readonly projectId: ProjectId;
  readonly name: string;
  readonly targetDate: IsoTimestamp | null;
}): Promise<Milestone> {
  const stamp = toIsoTimestamp(new Date());
  const row = getDb()
    .insert(milestones)
    .values({
      id: newId(),
      orgId: input.orgId,
      projectId: input.projectId,
      name: input.name,
      nameKey: milestoneNameKey(input.name),
      targetDate: input.targetDate,
      closedAt: null,
      createdAt: stamp,
      updatedAt: stamp,
    })
    .returning()
    .get();

  return toMilestone(row);
}

export async function updateMilestone(
  orgId: OrgId,
  milestoneId: MilestoneId,
  changes: MilestoneChanges,
): Promise<Milestone> {
  const row = getDb()
    .update(milestones)
    .set({
      ...(changes.name === undefined
        ? {}
        : { name: changes.name, nameKey: milestoneNameKey(changes.name) }),
      ...(changes.targetDate === undefined
        ? {}
        : { targetDate: changes.targetDate }),
      updatedAt: toIsoTimestamp(new Date()),
    })
    .where(
      and(
        orgPredicate(milestones.orgId, orgId),
        eq(milestones.id, milestoneId),
      ),
    )
    .returning()
    .get();

  if (!row) throw new Error(`Milestone ${milestoneId} not found`);
  return toMilestone(row);
}

export async function reopenMilestone(
  orgId: OrgId,
  milestoneId: MilestoneId,
): Promise<Milestone> {
  const stamp = toIsoTimestamp(new Date());
  const row = getDb()
    .update(milestones)
    .set({ closedAt: null, updatedAt: stamp })
    .where(
      and(
        orgPredicate(milestones.orgId, orgId),
        eq(milestones.id, milestoneId),
      ),
    )
    .returning()
    .get();

  if (!row) throw new Error(`Milestone ${milestoneId} not found`);
  return toMilestone(row);
}

/**
 * Closes a milestone and moves its open live issues in one transaction, so a
 * failure part-way cannot leave the milestone closed with issues still in it.
 * Closed and archived issues stay where they are.
 */
export async function closeMilestone(input: {
  readonly orgId: OrgId;
  readonly milestoneId: MilestoneId;
  readonly moveOpenIssuesTo: MilestoneId | null;
}): Promise<{
  readonly milestone: Milestone;
  readonly movedIssueIds: readonly IssueId[];
}> {
  const stamp = toIsoTimestamp(new Date());

  return getDb().transaction((tx) => {
    const moved = tx
      .update(issues)
      .set({ milestoneId: input.moveOpenIssuesTo, updatedAt: stamp })
      .where(
        and(
          ...compact(
            orgPredicate(issues.orgId, input.orgId),
            eq(issues.milestoneId, input.milestoneId),
            livePredicate(issues.archivedAt, {}),
            notInArray(issues.status, [...CLOSED_ISSUE_STATUSES]),
          ),
        ),
      )
      .returning({ id: issues.id })
      .all();

    const row = tx
      .update(milestones)
      .set({ closedAt: stamp, updatedAt: stamp })
      .where(
        and(
          orgPredicate(milestones.orgId, input.orgId),
          eq(milestones.id, input.milestoneId),
        ),
      )
      .returning()
      .get();

    if (!row) throw new Error(`Milestone ${input.milestoneId} not found`);

    return {
      milestone: toMilestone(row),
      movedIssueIds: moved.map((issue) => issue.id as IssueId),
    };
  });
}

/**
 * Progress for each milestone over its live issues, counted in SQL so the
 * answer does not depend on how many issues there are. A milestone with no
 * issues is absent from the map; callers treat that as all zeros.
 */
export async function progressByMilestone(
  orgId: OrgId,
  milestoneIds: readonly MilestoneId[],
): Promise<ReadonlyMap<MilestoneId, MilestoneProgress>> {
  const progress = new Map<MilestoneId, MilestoneProgress>();
  if (milestoneIds.length === 0) return progress;

  const db = getDb();
  const scope = and(
    ...compact(
      orgPredicate(issues.orgId, orgId),
      inArray(issues.milestoneId, [...milestoneIds]),
      livePredicate(issues.archivedAt, {}),
    ),
  );

  const totals = db
    .select({ milestoneId: issues.milestoneId, value: count() })
    .from(issues)
    .where(scope)
    .groupBy(issues.milestoneId)
    .all();

  const closedRows = db
    .select({ milestoneId: issues.milestoneId, value: count() })
    .from(issues)
    .where(and(scope, inArray(issues.status, [...CLOSED_ISSUE_STATUSES])))
    .groupBy(issues.milestoneId)
    .all();

  const closedBy = new Map(closedRows.map((row) => [row.milestoneId, row.value]));

  for (const row of totals) {
    if (row.milestoneId === null) continue;
    const closed = closedBy.get(row.milestoneId) ?? 0;
    progress.set(row.milestoneId as MilestoneId, {
      total: row.value,
      open: row.value - closed,
      closed,
    });
  }

  return progress;
}

